);

CREATE TABLE IF NOT EXISTS public."carrito" (
    "idcarrito" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "estado" VARCHAR(255) NOT NULL,
    "creado_en" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "actualizado_en" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
