ALTER TABLE public."carrito_items" ADD CONSTRAINT "fk_carrito_items_idcarrito" FOREIGN KEY ("idcarrito") REFERENCES public."carrito" ("idcarrito");
ALTER TABLE public."carrito_items" ADD CONSTRAINT "fk_carrito_items_idproductos_bar" FOREIGN KEY ("idproductos_bar") REFERENCES public."productos_bar" ("idproductos_bar");
