ALTER TABLE public."clientes" ADD CONSTRAINT "fk_clientes_usuario_id" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id");
ALTER TABLE public."ejerccios_rutina" ADD CONSTRAINT "fk_ejerccios_rutina_rutina_id" FOREIGN KEY ("rutina_id") REFERENCES public."rutinas" ("id");
ALTER TABLE public."historial_membresia" ADD CONSTRAINT "fk_historial_membresia_membresia_id" FOREIGN KEY ("membresia_id") REFERENCES public."membresias" ("id");
ALTER TABLE public."inscripciones_aerobicas" ADD CONSTRAINT "fk_inscripciones_aerobicas_clase_id" FOREIGN KEY ("clase_id") REFERENCES public."clases_aerobicas" ("id");
ALTER TABLE public."inscripciones_aerobicas" ADD CONSTRAINT "fk_inscripciones_aerobicas_cliente_id" FOREIGN KEY ("cliente_id") REFERENCES public."clientes" ("id");
ALTER TABLE public."inventario_general_movimientos" ADD CONSTRAINT "fk_inventario_general_movimientos_item_id" FOREIGN KEY ("item_id") REFERENCES public."inventario_general_items" ("id");
ALTER TABLE public."mantenimientos_equipos" ADD CONSTRAINT "fk_mantenimientos_equipos_equipo_id" FOREIGN KEY ("equipo_id") REFERENCES public."equipos" ("id");
ALTER TABLE public."mantenimientos_equipos" ADD CONSTRAINT "fk_mantenimientos_equipos_tecnico_id" FOREIGN KEY ("tecnico_id") REFERENCES public."personal" ("id");
ALTER TABLE public."membresias" ADD CONSTRAINT "fk_membresias_cliente_id" FOREIGN KEY ("cliente_id") REFERENCES public."clientes" ("id");
ALTER TABLE public."membresias" ADD CONSTRAINT "fk_membresias_creada_por_id" FOREIGN KEY ("creada_por_id") REFERENCES public."usuarios" ("id");
ALTER TABLE public."membresias" ADD CONSTRAINT "fk_membresias_plan_id" FOREIGN KEY ("plan_id") REFERENCES public."planes" ("id");
ALTER TABLE public."movimientos_caja" ADD CONSTRAINT "fk_movimientos_caja_caja_id" FOREIGN KEY ("caja_id") REFERENCES public."cajas" ("id");
ALTER TABLE public."movimientos_caja" ADD CONSTRAINT "fk_movimientos_caja_usuario_id" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id");
ALTER TABLE public."pagos" ADD CONSTRAINT "fk_pagos_membresia_id" FOREIGN KEY ("membresia_id") REFERENCES public."membresias" ("id");
ALTER TABLE public."pagos" ADD CONSTRAINT "fk_pagos_registrado_por_id" FOREIGN KEY ("registrado_por_id") REFERENCES public."usuarios" ("id");
ALTER TABLE public."pedidos_bar" ADD CONSTRAINT "fk_pedidos_bar_idcarrito" FOREIGN KEY ("idcarrito") REFERENCES public."carrito" ("idcarrito");
ALTER TABLE public."pedidos_bar" ADD CONSTRAINT "fk_pedidos_bar_idmetodos_pago" FOREIGN KEY ("idmetodos_pago") REFERENCES public."metodos_pago" ("idmetodos_pago");
