ALTER TABLE public."rutinas" ADD CONSTRAINT "fk_rutinas_cliente_id" FOREIGN KEY ("cliente_id") REFERENCES public."clientes" ("id");
ALTER TABLE public."rutinas" ADD CONSTRAINT "fk_rutinas_creada_por_id" FOREIGN KEY ("creada_por_id") REFERENCES public."usuarios" ("id");

-- Tablas complementarias solicitadas
-- 1. Pagos a administrativos, instructores y personal de limpieza.
CREATE TABLE IF NOT EXISTS public.pagos_personal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    personal_id BIGINT NOT NULL REFERENCES public.personal(id) ON DELETE RESTRICT,
    registrado_por_id BIGINT NOT NULL REFERENCES public.usuarios(id) ON DELETE RESTRICT,
    periodo_inicio DATE NOT NULL,
    periodo_fin DATE NOT NULL,
    monto NUMERIC(12,2) NOT NULL CHECK (monto > 0),
    fecha_pago TIMESTAMP WITHOUT TIME ZONE,
    metodo_pago VARCHAR(20) CHECK (metodo_pago IN ('EFECTIVO', 'QR')),
    estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE'
        CHECK (estado IN ('PENDIENTE', 'PAGADO', 'ANULADO')),
    observacion TEXT,
    creado_en TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_pagos_personal_periodo CHECK (periodo_fin >= periodo_inicio),
    CONSTRAINT ck_pagos_personal_pagado CHECK (
        estado <> 'PAGADO' OR (fecha_pago IS NOT NULL AND metodo_pago IS NOT NULL)
    ),
    CONSTRAINT uq_pagos_personal_periodo UNIQUE (personal_id, periodo_inicio, periodo_fin)
);
CREATE INDEX IF NOT EXISTS idx_pagos_personal_estado ON public.pagos_personal(estado);
CREATE INDEX IF NOT EXISTS idx_pagos_personal_fecha ON public.pagos_personal(fecha_pago);

-- 2. Auditoria de operaciones relevantes del sistema.
-- No guardar contrasenas, tokens JWT ni datos bancarios en JSONB.
CREATE TABLE IF NOT EXISTS public.auditoria_operaciones (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id BIGINT REFERENCES public.usuarios(id) ON DELETE SET NULL,
    accion VARCHAR(50) NOT NULL,
    entidad VARCHAR(100) NOT NULL,
    registro_id BIGINT,
    fecha TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    datos_anteriores JSONB,
    datos_nuevos JSONB,
    detalle TEXT,
    CONSTRAINT ck_auditoria_accion_no_vacia CHECK (length(btrim(accion)) > 0),
    CONSTRAINT ck_auditoria_entidad_no_vacia CHECK (length(btrim(entidad)) > 0)
);
CREATE INDEX IF NOT EXISTS idx_auditoria_fecha ON public.auditoria_operaciones(fecha DESC);
CREATE INDEX IF NOT EXISTS idx_auditoria_usuario ON public.auditoria_operaciones(usuario_id);
CREATE INDEX IF NOT EXISTS idx_auditoria_entidad_registro ON public.auditoria_operaciones(entidad, registro_id);

-- 3. Comprobantes de pagos de membresia.
-- Si un comprobante se genera solo a partir de pagos y no necesita
-- persistencia, esta tabla puede omitirse. Se incluye por solicitud.
CREATE TABLE IF NOT EXISTS public.comprobantes_pago (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pago_id BIGINT NOT NULL REFERENCES public.pagos(id) ON DELETE RESTRICT,
    numero VARCHAR(60) NOT NULL UNIQUE,
    tipo VARCHAR(20) NOT NULL DEFAULT 'RECIBO'
        CHECK (tipo IN ('RECIBO', 'FACTURA')),
    fecha_emision TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    archivo_url TEXT,
    emitido_por_id BIGINT REFERENCES public.usuarios(id) ON DELETE SET NULL,
    estado VARCHAR(20) NOT NULL DEFAULT 'EMITIDO'
        CHECK (estado IN ('EMITIDO', 'ANULADO')),
    observacion TEXT,
    CONSTRAINT uq_comprobantes_pago UNIQUE (pago_id, tipo)
);
CREATE INDEX IF NOT EXISTS idx_comprobantes_fecha ON public.comprobantes_pago(fecha_emision DESC);


COMMIT;
